#!/usr/bin/env node
/**
 * Vendors the app's agent contract and generates the SDK's view of it.
 *
 *   npm run contract:sync -- --app <path to the app checkout>   copy the artifact, regenerate the generated file
 *   npm run contract:check                                      fail when the vendored copy or the generated file is stale
 *   npm run contract:check -- --app <path>                      also fail when the app's artifact differs from the vendored copy
 *
 * The app declares the contract (`lib/api/contract`) and emits `contract/agent-contract.json`; nothing here is
 * written by hand. The artifact is canonical JSON whose `version` is the sha256 of everything else, so a copy is
 * current exactly when its version matches, and the check re-derives that hash rather than trusting the field.
 */
import { createHash } from 'node:crypto'
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const VENDORED = resolve(root, 'packages/sdk/contract/agent-contract.json')
const GENERATED = resolve(root, 'packages/sdk/src/contract.generated.ts')

const args = process.argv.slice(2)
const mode = args[0] === 'check' ? 'check' : 'sync'
const appFlag = args.indexOf('--app')
const appPath = appFlag >= 0 ? args[appFlag + 1] : undefined

const fail = (message) => {
  console.error(message)
  process.exit(1)
}

const sortKeys = (v) =>
  Array.isArray(v)
    ? v.map(sortKeys)
    : v && typeof v === 'object'
      ? Object.fromEntries(Object.keys(v).sort().map((k) => [k, sortKeys(v[k])]))
      : v

/** Parses the artifact and proves its `version` is the hash of its own content. */
function readContract(file) {
  const text = readFileSync(file, 'utf8')
  const doc = JSON.parse(text)
  const { version, ...body } = doc
  const expected = createHash('sha256').update(JSON.stringify(sortKeys(body))).digest('hex')
  if (version !== expected) fail(`${file}: version ${String(version).slice(0, 12)} is not the hash of its content (${expected.slice(0, 12)}). The file was edited by hand or damaged.`)
  return { text, doc }
}

// ---------------------------------------------------------------------------
// JSON Schema -> TypeScript. The contract uses a small, closed subset (zod's draft-7 output, every $ref inlined).
// ---------------------------------------------------------------------------

const IDENT = /^[A-Za-z_$][A-Za-z0-9_$]*$/
const key = (k) => (IDENT.test(k) ? k : JSON.stringify(k))
const lit = (v) => JSON.stringify(v)

function tsType(s, where) {
  if (s === true || s === undefined || (typeof s === 'object' && Object.keys(s).length === 0)) return 'unknown'
  if (s.const !== undefined) return lit(s.const)
  if (s.enum) return s.enum.map(lit).join(' | ')
  if (s.anyOf || s.oneOf) return (s.anyOf ?? s.oneOf).map((x) => tsType(x, where)).join(' | ')
  if (Array.isArray(s.type)) return s.type.map((t) => tsType({ ...s, type: t }, where)).join(' | ')
  switch (s.type) {
    case 'string': return 'string'
    case 'number':
    case 'integer': return 'number'
    case 'boolean': return 'boolean'
    case 'null': return 'null'
    case 'array': return `Array<${tsType(s.items, where)}>`
    case 'object': {
      const props = s.properties ?? {}
      const required = new Set(s.required ?? [])
      const members = Object.entries(props).map(([k, v]) => `${key(k)}${required.has(k) ? '' : '?'}: ${tsType(v, `${where}.${k}`)}`)
      const ap = s.additionalProperties
      if (ap && ap !== false) {
        const value = tsType(ap, where)
        if (members.length === 0) return `Record<string, ${value}>`
        members.push(`[extra: string]: unknown`)
      }
      return `{ ${members.join('; ')} }`
    }
    default:
      fail(`contract-sync: no TypeScript form for the schema at ${where}: ${JSON.stringify(s).slice(0, 120)}`)
  }
}

function generate(doc) {
  const names = doc.tools.map((t) => t.name)
  const out = []
  out.push(`/**
 * GENERATED by scripts/contract-sync.mjs from packages/sdk/contract/agent-contract.json. Do not edit.
 * Run \`npm run contract:sync -- --app <app checkout>\` to refresh it; \`npm run contract:check\` fails when it is stale.
 */
/* eslint-disable */

export interface ContractToolDescription {
  mcp: string
  inApp?: string
}

export interface ContractTool {
  name: string
  group: string
  scopes: readonly string[]
  description: ContractToolDescription
  inputSchema: { type: 'object'; properties: Record<string, ContractSchema>; required?: readonly string[]; additionalProperties?: unknown }
  inApp?: { omit?: Record<string, string>; optional?: Record<string, string>; narrow?: Record<string, { values: readonly string[]; reason: string }> }
}

/** A JSON Schema node of the contract: the draft-7 subset the app's declarations produce. */
export interface ContractSchema {
  type?: string | readonly string[]
  description?: string
  enum?: readonly unknown[]
  const?: unknown
  properties?: Record<string, ContractSchema>
  required?: readonly string[]
  items?: ContractSchema
  anyOf?: readonly ContractSchema[]
  oneOf?: readonly ContractSchema[]
  additionalProperties?: boolean | ContractSchema
  [key: string]: unknown
}

export interface AgentContract {
  tools: readonly ContractTool[]
  vocabularies: Record<string, readonly string[]>
  version: string
}

export const AGENT_CONTRACT_VERSION = ${lit(doc.version)}

export const AGENT_CONTRACT = ${JSON.stringify(doc, null, 2)} as unknown as AgentContract

export const CONTRACT_TOOL_NAMES = ${lit(names)} as const
export type ContractToolName = (typeof CONTRACT_TOOL_NAMES)[number]

/** The input of every tool, as the contract declares it. */
export interface ToolInputs {
${doc.tools.map((t) => `  ${key(t.name)}: ${tsType(t.inputSchema, t.name)}`).join('\n')}
}
export type ToolInput<N extends ContractToolName> = ToolInputs[N]

/** A tool's description for one audience. The in-app agent reads its own wording where the contract declares one. */
export function toolDescription(name: ContractToolName, audience: 'mcp' | 'in-app' = 'mcp'): string {
  const tool = AGENT_CONTRACT.tools.find((t) => t.name === name)
  if (!tool) throw new Error(\`No tool named \${name} in the agent contract\`)
  return audience === 'in-app' ? (tool.description.inApp ?? tool.description.mcp) : tool.description.mcp
}

/** A tool's input as JSON Schema. */
export function toolInputSchema(name: ContractToolName): ContractTool['inputSchema'] {
  const tool = AGENT_CONTRACT.tools.find((t) => t.name === name)
  if (!tool) throw new Error(\`No tool named \${name} in the agent contract\`)
  return tool.inputSchema
}
`)
  out.push('// Vocabularies, by the names the app declares them under.')
  for (const [name, values] of Object.entries(doc.vocabularies)) out.push(`export const ${name} = ${lit(values)} as const`)
  return out.join('\n')
}

// ---------------------------------------------------------------------------

if (mode === 'sync') {
  if (!appPath) fail('Usage: npm run contract:sync -- --app <path to the app checkout>')
  const source = resolve(appPath, 'contract/agent-contract.json')
  if (!existsSync(source)) fail(`No contract artifact at ${source}. Run \`npm run contract:emit\` in the app first.`)
  readContract(source)
  mkdirSync(dirname(VENDORED), { recursive: true })
  copyFileSync(source, VENDORED)
  const { doc } = readContract(VENDORED)
  writeFileSync(GENERATED, generate(doc))
  console.log(`synced agent contract ${doc.version.slice(0, 12)} (${doc.tools.length} tools)`)
} else {
  if (!existsSync(VENDORED)) fail('No vendored contract. Run `npm run contract:sync -- --app <path>`.')
  const { text, doc } = readContract(VENDORED)
  if (!existsSync(GENERATED) || readFileSync(GENERATED, 'utf8') !== generate(doc)) fail('packages/sdk/src/contract.generated.ts is stale. Run `npm run contract:sync -- --app <path>`.')
  if (appPath) {
    const source = resolve(appPath, 'contract/agent-contract.json')
    if (!existsSync(source)) fail(`No contract artifact at ${source}.`)
    if (readFileSync(source, 'utf8') !== text) fail(`The vendored contract differs from the app's (${source}). Run \`npm run contract:sync -- --app ${appPath}\`.`)
  }
  console.log(`agent contract is current (${doc.version.slice(0, 12)})`)
}
